package glitch

import data.glitch_lib

# Pattern to identify IP binding related attributes/variables
binding_pattern := "(?i).*(bind|ip|address|host|listen|server|net).*"

# Check if an expression contains "0.0.0.0" or similar unrestricted IP
contains_unrestricted_ip(expr) {
    walk(expr, [_, n])
    n.ir_type == "String"
    n.value == "0.0.0.0"
}

# Check if a hash contains an unrestricted IP in a binding-related key
check_hash_for_unrestricted_ip(hash_node) {
    some key_expr, value_expr
    value_expr := hash_node.value[key_expr]
    key_name := get_key_name(key_expr)
    regex.match(binding_pattern, key_name)
    contains_unrestricted_ip(value_expr)
}

# Get the key name from different key expression types
get_key_name(key) = name {
    key.ir_type == "VariableReference"
    # Remove leading colon if present (e.g., ":ip" -> "ip")
    name := trim_prefix(key.value, ":")
} else {
    key.ir_type == "String"
    name := key.value
} else {
    # For other types, try to get string representation
    name := key.code
}

# Helper to traverse all hashes in a node, including nested ones
all_hashes(node) = hashes {
    hashes = {n |
        walk(node, [path, n])
        n.ir_type == "Hash"
    }
}

# Rule 1: Check attributes in atomic units for unrestricted IP binding
